CREATE TABLE IF NOT EXISTS RoleDefinitions(Id INTEGER PRIMARY KEY AUTOINCREMENT,RoleName TEXT UNIQUE,Description TEXT,IsSystem INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS Permissions(Id INTEGER PRIMARY KEY AUTOINCREMENT,PermissionName TEXT UNIQUE,Description TEXT,Category TEXT);
CREATE TABLE IF NOT EXISTS RolePermissions(RoleId INTEGER,PermissionId INTEGER,PRIMARY KEY(RoleId,PermissionId),FOREIGN KEY(RoleId) REFERENCES RoleDefinitions(Id) ON DELETE CASCADE,FOREIGN KEY(PermissionId) REFERENCES Permissions(Id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS UserRoles(Id INTEGER PRIMARY KEY AUTOINCREMENT,UserAccount TEXT,RoleId INTEGER,AssignedOn TEXT,AssignedBy TEXT,UNIQUE(UserAccount,RoleId),FOREIGN KEY(RoleId) REFERENCES RoleDefinitions(Id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ReportPermissions(Id INTEGER PRIMARY KEY AUTOINCREMENT,ReportPath TEXT,RoleId INTEGER,CanView INTEGER DEFAULT 1,CanExecute INTEGER DEFAULT 0,UNIQUE(ReportPath,RoleId),FOREIGN KEY(RoleId) REFERENCES RoleDefinitions(Id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ActionPermissions(Id INTEGER PRIMARY KEY AUTOINCREMENT,ActionName TEXT,RoleId INTEGER,RequiresApproval INTEGER DEFAULT 0,UNIQUE(ActionName,RoleId),FOREIGN KEY(RoleId) REFERENCES RoleDefinitions(Id) ON DELETE CASCADE);
